"""Cross-language damage contract, generated by Rust's public producer."""

import copy
import json
from pathlib import Path

import pytest

from tools.expert.curated import _digest
from tools.expert.decision import DecisionReading, render_decision
from tools.expert.mechanics import _damage_delivery

FIXTURE = Path(__file__).parent / "fixtures/public-card-reward-damage.json"


def test_selected_damage_reading_separates_choices_hits_scope_and_conditions():
    reading = DecisionReading(FIXTURE)
    rows = reading.view("mechanics")["content"]["candidates"]
    by_card = {row["facts"]["current"]["card"]: row for row in rows}
    text_for = lambda card: render_decision(
        reading.view("mechanics", candidate_ordinals=[by_card[card]["ordinal"]])
    )
    wish = text_for("Wish")
    assert "伤害 3" in wish and "力量数值，不发出攻击伤害请求" in wish
    pummel = text_for("Pummel")
    assert "请求 4 段" in pummel and "请求 5 段" in pummel
    assert "Ragnarok" not in pummel and len(pummel) < 700
    assert "每段随机选一个敌人" in text_for("Ragnarok")
    assert "请求 5 段" in text_for("Ragnarok")
    assert "请求 6 段" in text_for("Ragnarok")
    assert "每个敌人分别承受这些段数" in text_for("DaggerSpray")
    assert "请求 2 段" in text_for("DaggerSpray")
    assert "消耗前手牌数" in text_for("FiendFire")
    assert "有效 X" in text_for("Whirlwind")
    assert "当前格挡替换" in text_for("BodySlam")
    assert "目标有中毒才追加一段" in text_for("Bane")
    assert "Strike 牌数量 × 2" in text_for("PerfectedStrike")
    assert "Strike 牌数量 × 3" in text_for("PerfectedStrike")
    assert "冰霜球数 × 2" in text_for("Blizzard")
    assert "冰霜球数 × 3" in text_for("Blizzard")
    assert "没有其他攻击牌才能打出" in text_for("SignatureMove")


@pytest.mark.parametrize("change", [
    lambda rule: rule.update(kind="future_unknown_attack"),
    lambda rule: rule.update(targets="all_random_enemy_total"),
    lambda rule: rule.update(targets=[]),
    lambda rule: rule.update(play_condition={}),
    lambda rule: rule["hits"].update(count=True),
    lambda rule: rule["hits"].update(count=-1),
    lambda rule: rule["hits"].update(unreviewed_bonus=2),
    lambda rule: rule.update(amount={"kind": "base_plus_strike_cards"}),
    lambda rule: rule.update(amount={"kind": "base_plus_strike_cards", "per_card": False}),
])
def test_unrendered_or_invalid_damage_rules_are_rejected(change):
    document = json.loads(FIXTURE.read_text(encoding="utf-8"))
    pummel = document["payload"]["card_mechanics"]["candidates"][1]
    rule = copy.deepcopy(pummel["facts"]["current"]["reviewed_effects"]["base_damage_delivery"])
    change(rule)
    with pytest.raises(ValueError):
        _damage_delivery(rule)


def test_old_reading_does_not_guess_hits_from_positive_definition_field(tmp_path):
    document = json.loads(FIXTURE.read_text(encoding="utf-8"))
    for row in document["payload"]["card_mechanics"]["candidates"]:
        for variant in (row["facts"]["current"], row["facts"]["next_upgrade"]):
            if variant is not None:
                variant["reviewed_effects"].pop("base_damage_delivery", None)
    document["payload_sha256"] = _digest(document["payload"])
    path = tmp_path / "old-reading.json"
    path.write_text(json.dumps(document), encoding="utf-8")
    text = render_decision(DecisionReading(path).view("mechanics", candidate_ordinals=[1]))
    assert "伤害 2" in text and "Unknown" in text
    assert "请求 4 段" not in text and "请求 1 段" not in text
